def log_msg(mensagem):
    linha = f"[{datetime.now().strftime('%Y-%m-%d %H:%M:%S')}] {mensagem}"
    print(linha)
    LOG_PATH.parent.mkdir(parents=True, exist_ok=True)
    with open(LOG_PATH, "a", encoding="utf-8") as f:
        f.write(linha + "\n")


def normalizar_texto(texto):
    """
    Padroniza strings (nomes):
    - Converte para maiúsculas.
    - Remove acentos e substitui Ç por C.
    - Remove pontuações e caracteres especiais.
    - Remove preposições comuns (DE, DA, DO, DAS, DOS, E) para evitar ruído no match.
    """
    if not isinstance(texto, str) or not texto.strip():
        return ""
    
    # Normaliza para separar caracteres e acentos (NFKD)
    nfkd = unicodedata.normalize('NFKD', texto)
    sem_acento = "".join([c for c in nfkd if not unicodedata.combining(c)])
    
    maiuscula = sem_acento.upper().replace('Ç', 'C')
    
    # Remove tudo o que não for letra ou número (tira pontuação)
    limpo = re.sub(r'[^A-Z0-9\s]', '', maiuscula)
    
    # Remove preposições e conectivos comuns
    palavras = [p for p in limpo.split() if p not in {'DE', 'DA', 'DO', 'DAS', 'DOS', 'E'}]
    
    return " " .join(palavras)


def request_json(url, method="GET", data=None, token=None):
    headers = {"Accept": "application/json"}
    body = None

    if data is not None:
        headers["Content-Type"] = "application/json"
        body = json.dumps(data).encode("utf-8")
    if token:
        headers["Authorization"] = f"Bearer {token}"

    request = urllib.request.Request(url, data=body, headers=headers, method=method)

    try:
        with urllib.request.urlopen(request, timeout=120) as response:
            return json.loads(response.read().decode("utf-8"))
    except urllib.error.HTTPError as error:
        detail = error.read().decode("utf-8", errors="replace")
        raise RuntimeError(f"Erro HTTP {error.code}: {detail}") from error
    except urllib.error.URLError as error:
        raise RuntimeError(f"Falha de conexão: {error.reason}") from error


def obter_usuarios_microsoft():
    tenant_id = os.getenv("AZURE_TENANT_ID")
    client_id = os.getenv("AZURE_CLIENT_ID")
    client_secret = os.getenv("AZURE_CLIENT_SECRET")

    if not all([tenant_id, client_id, client_secret]):
        log_msg("Aviso: Credenciais do Azure/Entra ID não configuradas no .env. Pulando busca na Microsoft.")
        return pd.DataFrame()

    log_msg("Autenticando no Microsoft Entra ID (Graph API)...")
    token_url = f"https://login.microsoftonline.com/{tenant_id}/oauth2/v2.0/token"
    
    body_data = urlencode({
        "client_id": client_id,
        "scope": "https://graph.microsoft.com/.default",
        "client_secret": client_secret,
        "grant_type": "client_credentials"
    }).encode("utf-8")

    req = urllib.request.Request(token_url, data=body_data, method="POST")
    try:
        with urllib.request.urlopen(req) as resp:
            token_resp = json.loads(resp.read().decode("utf-8"))
            access_token = token_resp.get("access_token")
    except Exception as e:
        raise RuntimeError(f"Erro ao autenticar no Entra ID: {e}")

    graph_url = "https://graph.microsoft.com/v1.0/users?$select=displayName,mail,userPrincipalName,accountEnabled,assignedLicenses"
    
    usuarios_ms = []
    while graph_url:
        resposta_graph = request_json(graph_url, token=access_token)
        usuarios_ms.extend(resposta_graph.get("value", []))
        graph_url = resposta_graph.get("@odata.nextLink")

    df_ms = pd.json_normalize(usuarios_ms)
    return df_ms


def main():
    log_msg("Iniciando pipeline unificado de auditoria e offboarding...")
    
    document = os.getenv("SIGO_DOCUMENT", "").strip()
    password = os.getenv("SIGO_PASSWORD", "")
    if not document:
        document = input("Documento de acesso ao SIGO: ").strip()
    if not password:
        password = getpass.getpass("Senha do SIGO: ")
    if not document or not password:
        raise SystemExit("Documento e senha são obrigatórios.")

    endpoint = urlsplit(ENDPOINT_SIGO)
    auth_url = f"{endpoint.scheme}://{endpoint.netloc}/auth/login"
    login = request_json(auth_url, method="POST", data={"document": document, "password": password})

    token_sigo = login.get("accessToken")
    if not token_sigo:
        raise RuntimeError("A autenticação do SIGO não retornou accessToken.")

    response_sigo = request_json(ENDPOINT_SIGO, token=token_sigo)
    records_sigo = response_sigo.get("data", []) if isinstance(response_sigo, dict) else response_sigo
    df_sigo = pd.json_normalize(records_sigo)

    if df_sigo.empty:
        OUTPUT_DESLIGADOS_CSV.parent.mkdir(parents=True, exist_ok=True)
        pd.DataFrame(columns=["UserPrincipalName", "ChapaSIGO", "NomeSIGO"]).to_csv(
            OUTPUT_DESLIGADOS_CSV, index=False, sep=";"
        )
        pd.DataFrame(columns=["ChapaSIGO", "NomeSIGO", "EmailSIGO", "Motivo"]).to_csv(
            OUTPUT_VERIFICAR_CSV, index=False, sep=";"
        )
        log_msg("O SIGO retornou uma base vazia. Os CSVs foram gerados sem registros.")
        return

    if "isactive" in df_sigo.columns:
        df_sigo["isactive"] = df_sigo["isactive"].astype(str).str.lower().map({'true': True, 'false': False, '1': True, '0': False})
        desligados_sigo = df_sigo[df_sigo["isactive"] == False].copy()
    else:
        raise RuntimeError("Coluna 'isactive' não encontrada no SIGO.")

    nome_colunas_possiveis = ("nome", "name", "displayName")
    col_nome_sigo = next(
        (coluna for coluna in nome_colunas_possiveis if coluna in desligados_sigo.columns),
        None,
    )
    if col_nome_sigo is None:
        raise RuntimeError(
            "Coluna de nome do colaborador não encontrada no SIGO "
            "(esperada: nome, name ou displayName)."
        )

    log_msg(f"Total de inativos encontrados no SIGO: {len(desligados_sigo)}")

    chapa_col = "externalid" if "externalid" in desligados_sigo.columns else None
    if chapa_col:
        desligados_sigo = desligados_sigo[~desligados_sigo[chapa_col].astype(str).str.strip().isin(CHAPAS_IGNORADAS)]
    nomes_ignorados_normalizados = {
        normalizar_texto(nome) for nome in NOMES_IGNORADOS if isinstance(nome, str) and nome.strip()
    }
    if nomes_ignorados_normalizados:
        desligados_sigo = desligados_sigo[
            ~desligados_sigo[col_nome_sigo].apply(normalizar_texto).isin(nomes_ignorados_normalizados)
        ]
    if "email" in desligados_sigo.columns:
        desligados_sigo = desligados_sigo[~desligados_sigo["email"].astype(str).str.strip().str.lower().isin({e.lower() for e in EMAILS_IGNORADOS})]

    log_msg(f"Registros restantes após ignorar exceções: {len(desligados_sigo)}")

    OUTPUT_DESLIGADOS_CSV.parent.mkdir(parents=True, exist_ok=True)
    if desligados_sigo.empty:
        pd.DataFrame(columns=["UserPrincipalName", "ChapaSIGO", "NomeSIGO"]).to_csv(
            OUTPUT_DESLIGADOS_CSV, index=False, sep=";"
        )
        pd.DataFrame(columns=["ChapaSIGO", "NomeSIGO", "EmailSIGO", "Motivo"]).to_csv(
            OUTPUT_VERIFICAR_CSV, index=False, sep=";"
        )
        log_msg("Nenhum registro restante após os filtros. Os CSVs foram gerados sem registros.")
        return

    df_ms = obter_usuarios_microsoft()

    # Sem os dados da Microsoft, não há registros seguros para processar automaticamente.
    if df_ms.empty:
        log_msg("Aviso: comparação com a Microsoft ignorada. Nenhuma conta será enviada ao PowerShell.")
        pd.DataFrame(columns=["UserPrincipalName", "ChapaSIGO", "NomeSIGO"]).to_csv(
            OUTPUT_DESLIGADOS_CSV, index=False, sep=";"
        )
        pd.DataFrame(
            [
                {
                    "ChapaSIGO": row.get("externalid", "N/A"),
                    "NomeSIGO": row.get(col_nome_sigo, ""),
                    "EmailSIGO": row.get("email", ""),
                    "Motivo": "Comparação com a Microsoft não realizada",
                }
                for _, row in desligados_sigo.iterrows()
            ],
            columns=["ChapaSIGO", "NomeSIGO", "EmailSIGO", "Motivo"],
        ).to_csv(OUTPUT_VERIFICAR_CSV, index=False, sep=";")
        return

    colunas_ms_necessarias = {"displayName", "mail", "userPrincipalName", "assignedLicenses"}
    colunas_ms_ausentes = colunas_ms_necessarias.difference(df_ms.columns)
    if colunas_ms_ausentes:
        raise RuntimeError(
            "A resposta do Microsoft Graph não contém as colunas necessárias: "
            + ", ".join(sorted(colunas_ms_ausentes))
        )

    # Normaliza os nomes para permitir o cruzamento entre SIGO e Microsoft.
    desligados_sigo["nome_normalizado"] = desligados_sigo[col_nome_sigo].apply(normalizar_texto)
    
    df_ms["nome_normalizado"] = df_ms["displayName"].apply(normalizar_texto)
    
    # Usa o e-mail como primeira opção de correspondência, quando disponível.
    col_email_sigo = "email" if "email" in desligados_sigo.columns else None

    para_desativar = []
    para_verificar = []

    for _, row_sigo in desligados_sigo.iterrows():
        email_sigo = str(row_sigo.get(col_email_sigo, "")).strip().lower() if col_email_sigo else ""
        nome_norm_sigo = row_sigo["nome_normalizado"]
        chapa_sigo = row_sigo.get("externalid", "N/A")

        encontrado = None

        if email_sigo and "mail" in df_ms.columns:
            match_email = df_ms[df_ms["mail"].str.lower().str.strip() == email_sigo]
            if not match_email.empty:
                encontrado = match_email.iloc[0]

        if encontrado is None and nome_norm_sigo:
            match_nome = df_ms[df_ms["nome_normalizado"] == nome_norm_sigo]
            if not match_nome.empty:
                encontrado = match_nome.iloc[0]

        if encontrado is not None:
            licenses = encontrado.get("assignedLicenses", [])
            tem_licenca = isinstance(licenses, list) and len(licenses) > 0

            if tem_licenca:
                para_desativar.append({
                    "UserPrincipalName": encontrado.get("userPrincipalName") or encontrado.get("mail"),
                    "ChapaSIGO": chapa_sigo,
                    "NomeSIGO": row_sigo.get(col_nome_sigo)
                })
            else:
                para_verificar.append({
                    "ChapaSIGO": chapa_sigo,
                    "NomeSIGO": row_sigo.get(col_nome_sigo),
                    "EmailSIGO": email_sigo,
                    "Motivo": "Inativo no SIGO e encontrado na Microsoft, mas já está sem licenças atribuídas"
                })
        else:
            para_verificar.append({
                "ChapaSIGO": chapa_sigo,
                "NomeSIGO": row_sigo.get(col_nome_sigo),
                "EmailSIGO": email_sigo,
                "Motivo": "Inativo no SIGO mas não encontrado na Microsoft"
            })


    OUTPUT_DESLIGADOS_CSV.parent.mkdir(parents=True, exist_ok=True)
    
    df_desativar = pd.DataFrame(para_desativar)
    df_desativar.to_csv(OUTPUT_DESLIGADOS_CSV, index=False, sep=";")
    pd.DataFrame(
        para_verificar,
        columns=["ChapaSIGO", "NomeSIGO", "EmailSIGO", "Motivo"],
    ).to_csv(OUTPUT_VERIFICAR_CSV, index=False, sep=";")
    
    log_msg("Processamento de dados concluído com sucesso.")
    log_msg(f"-> Contas prontas para o PowerShell (`desligados_para_powershell.csv`): {len(df_desativar)}")
    log_msg(f"-> Contas para auditoria manual (`para_verificar_manual.csv`): {len(para_verificar)}")

    if not df_desativar.empty:
        caminho_ps1 = PASTA_SCRIPT.parent / "powershell" / "offboarding.ps1"

        if not caminho_ps1.is_file() or caminho_ps1.stat().st_size == 0:
            raise RuntimeError(
                f"CSV gerado, mas o script PowerShell não existe ou está vazio: {caminho_ps1}"
            )

        log_msg("Iniciando a execução do script PowerShell de offboarding...")
        try:
            resultado = subprocess.run(
                [
                    "powershell.exe",
                    "-NoProfile",
                    "-NonInteractive",
                    "-ExecutionPolicy",
                    "Bypass",
                    "-File",
                    str(caminho_ps1),
                ],
                capture_output=True,
                text=True,
                check=True,
            )
        except subprocess.CalledProcessError as error:
            log_msg(f"Falha ao executar o PowerShell (código {error.returncode}).")
            if error.stderr:
                log_msg(f"Detalhes do erro PowerShell: {error.stderr.strip()}")
            raise RuntimeError("A execução do PowerShell falhou.") from error
        except OSError as error:
            log_msg(f"Não foi possível iniciar o PowerShell: {error}")
            raise RuntimeError("Não foi possível iniciar o PowerShell.") from error

        log_msg("Script PowerShell executado com sucesso.")
        if resultado.stdout:
            log_msg(f"Saída do PowerShell:\n{resultado.stdout.strip()}")
        log_msg(f"AUDITORIA: {len(df_desativar)} conta(s) enviada(s) para processamento no PowerShell.")
    else:
        log_msg("Nenhuma conta nova para enviar ao PowerShell. Nenhuma licença processada neste ciclo.")


if __name__ == "__main__":
    try:
        main()
    except Exception as error:
        log_msg(f"Falha no pipeline ({type(error).__name__}): {error}")
        raise